func validate(_ password: String) throws {
    guard password.count >= 8 else {
        throw PasswordError.tooShort(minimum: 8)
    }
    guard password.contains(where: { $0.isNumber }) else {
        throw PasswordError.noDigit
    }
}
func changePassword(to password: String) throws {
    try validate(password)
    savedPassword = password
}
do {
    try changePassword(to: "кот7")
    assertionFailure("Ожидалась ошибка")
} catch {
    assert(error as? PasswordError == .tooShort(minimum: 8))
}
assert(savedPassword.isEmpty)

Связанное значение несёт данные ошибки: экран покажет «Минимум 8 символов» без отдельной константы. changePassword помечена throws и вызывает try validate без do/catch — ошибка уходит к вызывающему, а строка сохранения не выполняется. Поэтому после неудачи savedPassword остаётся пустым.

