enum SaveError: Error { case diskFull }
var freeBytes = 0
func save(_ draft: String) throws {
    guard draft.utf8.count <= freeBytes else { throw SaveError.diskFull }
    freeBytes -= draft.utf8.count
}
var banner = ""
func saveTapped(_ draft: String) {
    do {
        try save(draft)
    } catch {
        banner = "Не сохранено: нет места"
    }
    banner = "Черновик сохранён"
}
saveTapped("Привет, Оля!")
print(banner)

key:
func saveTapped(_ draft: String) {
    do {
        try save(draft)
        banner = "Черновик сохранён"
    } catch {
        banner = "Не сохранено: нет места"
    }
}

Строка успеха стоит после всего do/catch и выполняется при любом исходе: catch ставит текст ошибки, следующая строка его затирает. Успех пишут внутри do сразу после try — туда попадаем, только если save не бросил. Теперь вывод «Не сохранено: нет места».

